#include <assert.h>
#include "servo_controller.h"
int main(void){const servo_config_t cfg={0U,180U,500U,2500U,20000U};assert(servo_config_is_valid(&cfg));assert(servo_clamp_angle(&cfg,-1)==0U);assert(servo_clamp_angle(&cfg,200)==180U);assert(servo_angle_to_pulse_us(&cfg,0U)==500U);assert(servo_angle_to_pulse_us(&cfg,90U)==1500U);assert(servo_angle_to_pulse_us(&cfg,180U)==2500U);assert(servo_pulse_us_to_compare(1500U,1000000U)==1500U);servo_controller_t c;assert(servo_controller_init(&c,&cfg,90U,10U));servo_controller_set_target(&c,120);assert(servo_controller_step(&c)==1611U&&c.current_angle_deg==100U);assert(servo_controller_step(&c)==1722U&&c.current_angle_deg==110U);assert(servo_controller_step(&c)==1833U&&c.current_angle_deg==120U);assert(servo_controller_at_target(&c));servo_controller_set_target(&c,999);assert(c.target_angle_deg==180U&&c.clamp_count==1U);return 0;}
